export function localizeCatalogText(language: UiLanguage, value: string) {
  return (CATALOG_TEXT[language] ?? []).reduce((text, [source, translated]) => text.replaceAll(source, translated), value)
    .replace(/\bOT\b/g, language.startsWith("ES") ? "EO" : language === "FRA" ? "DO" : language === "ITA" ? "AO" : language === "DEU" ? "OT" : language === "ENG" ? "OT" : language === "JPN" ? "親名" : language === "KOR" ? "어버이" : language === "CHT" ? "訓練家" : "训练家");
}


export function formName(language: UiLanguage, dex: number, form: string | null) {
  if (!form) return null;
  return dex === 666 ? VIVILLON_FORMS[form]?.[language] ?? form : form;
}

const ES_ES_COPY: Copy = {
  profile_shiny_basic: "Living Dex variocolor",
  profile_shiny_basic_desc: "Un ejemplar variocolor obtenible de cada especie.",
  profile_shiny_final: "Dex variocolor de fases finales",
  profile_shiny_final_desc: "Formas regionales y todos los variocolor obtenibles en su última etapa evolutiva.",
  profile_shiny_regional: "Living Dex variocolor + formas regionales",
  profile_shiny_regional_desc: "Cada especie variocolor obtenible y todas sus formas regionales.",
  profile_shiny_forms_lite: "Living Dex variocolor de formas simplificada",
  profile_shiny_forms_lite_desc: "Todas las formas variocolor obtenibles, sin posiciones extra por diferencias de sexo.",
  profile_shiny: "Living Dex variocolor de formas",
  profile_shiny_desc: "Todas las formas variocolor obtenibles y diferencias de sexo visibles con tu EO.",
  shiny_available: "Variocolor disponible",
  shiny_locked: "Variocolor bloqueado",
};

export function copy(language: UiLanguage, key: string) {
  if (key === "box") return ({ "ES-LA": "CAJA", "ES-ES": "CAJA", ENG: "BOX", DEU: "BOX", FRA: "BOÎTE", ITA: "BOX", JPN: "ボックス", KOR: "박스", CHS: "盒子", CHT: "盒子" } as Record<UiLanguage, string>)[language];
  if (language === "ES-ES" && ES_ES_COPY[key]) return ES_ES_COPY[key];
  if (FORM_FILTER_COPY[language][key]) return FORM_FILTER_COPY[language][key];
  if (language === "CHT" && key === "preset_normal") return "一般顏色";
  if (language === "CHT" && key === "preset_normal_desc") return "一般顏色的個體";
  if (language === "CHT" && key === "normal_living_dex") return "一般 Living Dex";
  if (language === "CHT" && key === "normal_living_dex_desc") return "每個種類一隻 · 保留篩選";
  if (key === "preset_normal" || key === "preset_normal_desc") return UI_COPY[language][key] ?? ES[key] ?? key;
  return NAVIGATION_BACKUP_COPY[language]?.[key] ?? AUSTIN_IMPORT_COPY[language]?.[key] ?? AUSTIN_IMPORT_EN[key] ?? SIDEBAR_COPY[language]?.[key] ?? FEATURE_COPY[language]?.[key] ?? FEATURE_EN[key] ?? GLOBAL_VIEW_COPY[language][key] ?? UI_OVERRIDES[language][key] ?? UI_COPY[language][key] ?? ES[key] ?? key;
}

export function hasCopy(language: UiLanguage, key: string) {
  if (key === "box") return true;
  if (language === "ES-ES" && Object.hasOwn(ES_ES_COPY, key)) return true;
  if (Object.hasOwn(FORM_FILTER_COPY[language], key)) return true;
  if (key === "preset_normal" || key === "preset_normal_desc" || key === "normal_living_dex" || key === "normal_living_dex_desc") return true;
  if (copy(language, key) !== key) return true;
  return [AUSTIN_IMPORT_EN, FEATURE_EN, GLOBAL_VIEW_COPY.ENG, UI_COPY.ENG, ES]
    .some((source) => Object.hasOwn(source, key));
}

export function groupName(language: UiLanguage, key: string) {
  return GROUPS[key]?.[language] ?? (language.startsWith("ES") ? ({ P: "Pentágono", USUM: "Alola", LGPE: "Let's Go", SwSh: "Galar", LA: "Hisui", BDSP: "Sinnoh", SV: "Escarlata / Púrpura", LZA: "Lumiose", GBA: "GBA", "Sin marca": "Sin marca", GB: "GB", n: "Pokémon de N", dream: "Dream World", radar: "Pokémon Dream Radar", "shadow-colosseum": "Shadow · Colosseum", "shadow-xd": "Shadow · XD", cherish: "Cherish Ball", mighty: "Incursiones con Emblema Imbatibilidad", trades: "Intercambios internos", go: "Pokémon GO" } as Record<string, string>)[key] : undefined) ?? key;
}
